$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-top3-r1.mjs'
try{
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},10000);
try{const v=await(await fetch('http://127.0.0.1:17447/json/version')).json();const w=new WebSocket(v.webSocketDebuggerUrl);
await new Promise((ok,no)=>{w.addEventListener('open',ok,{once:true});w.addEventListener('error',no,{once:true})});
let seq=0,p=new Map();w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(p.has(z.id)){p.get(z.id)(z);p.delete(z.id)}});
const send=(method,params)=>Promise.race([new Promise(resolve=>{const id=++seq;p.set(id,resolve);w.send(JSON.stringify({id,method,params}))}),new Promise(resolve=>setTimeout(()=>resolve({error:{message:'timeout'}}),2500))]);
const data=[];for(const url of ["https://www.avito.ru/krasnoyarsk/telefony/iphone_15_pro_max_256_gb_8220958313","https://www.avito.ru/krasnoyarsk/telefony/iphone_15_pro_max_256_gb_sim_esim_8253352006","https://www.avito.ru/krasnoyarsk/telefony/iphone_15_pro_max_256_gb_sim_esim_8358178736"]){const z=await send('Target.createTarget',{url,background:true,newWindow:false});data.push({url,target_id:z.result?.targetId||null,error:z.error?.message||null})}
const active=data[0]?.target_id?(await send('Target.activateTarget',{targetId:data[0].target_id})):null;
console.log(JSON.stringify({data,firstActivated:!!active?.result}));process.exit(0);
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,140)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue}
